CREATE COLUMN TABLE "TEST_AP"."OIMT" ("ValuatType" NVARCHAR(1) DEFAULT 'N' NOT NULL , "TransType" INTEGER CS_INT DEFAULT -1 NOT NULL , "BaseType" SMALLINT CS_INT DEFAULT -1 NOT NULL , "TemplateId" SMALLINT CS_INT DEFAULT -1 NOT NULL , "LocalizId" NVARCHAR(2) DEFAULT 'XX' NOT NULL , "Action" SMALLINT CS_INT DEFAULT 0 NOT NULL , "JEPosting" NVARCHAR(1) DEFAULT 'N', "LineActTyp" SMALLINT CS_INT DEFAULT 2, "TmpType" SMALLINT CS_INT DEFAULT 0 NOT NULL , "Total" NVARCHAR(1) DEFAULT 'M', PRIMARY KEY ("TemplateId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OIMT_SECONDARY" ON "TEST_AP"."OIMT" ( "TransType" ASC, "BaseType" ASC, "ValuatType" ASC, "LocalizId" ASC, "Action" ASC, "TmpType" ASC )